T={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
# generate D4 transformations
transforms=[]
for k in range(4):
    for refl in [False,True]:
        def tf(p,k=k,refl=refl):
            r,c=p
            if refl: c=-c
            for _ in range(k): r,c=c,-r
            return r,c
        raw=[tf(p) for p in T]
        minr=min(r for r,c in raw); minc=min(c for r,c in raw)
        S=frozenset((r-minr,c-minc) for r,c in raw)
        if S not in [s for _,s in transforms]: transforms.append((('r',k,'f',refl),S))
print(len(transforms),[(a,sorted(s)) for a,s in transforms])
def placements(seed):
    seed=set(seed); res=[]
    for tag,S in transforms:
        for sr,sc in seed:
            for tr,tc in S:
                dr,dc=sr-tr,sc-tc
                placed={(r+dr,c+dc) for r,c in S}
                if seed <= placed and (tag,dr,dc) not in [x[:3] for x in res]:
                    res.append((tag,dr,dc,placed))
    return res
